namespace detail {
    template <typename T>
    struct SingletonStorage {
        static inline T instance;
    };
}

template <typename T, typename... Args>
class Singleton {
public:
    static T& Instance(Args&&... args) {
        static T instance(std::forward<Args>(args)...);
        return instance;
    }
};

template <typename T, typename... Args>
class SingletonPtr {
public:
    static std::shared_ptr<T> Instance(Args&&... args) {
        static auto instance = std::make_shared<T>(std::forward<Args>(args)...);
        return instance;
    }
};

template <typename T, typename Cleaner>
class RAII {
public:
    explicit RAII(T obj, Cleaner cleaner) : obj_(std::move(obj)), cleaner_(cleaner) {}
    ~RAII() {
        if (cleaner_) cleaner_();
    }
private:
    T obj_;
    Cleaner cleaner_;
};

class MappedReadOnlyFile {
public:
    explicit MappedReadOnlyFile(std::string path) : path_(std::move(path)) {}
    ~MappedReadOnlyFile() {
        Unmap();
    }
    std::byte* Map();
    void Unmap();
    std::size_t Size() const noexcept { return stat_.st_size; }
    std::byte* Data() const noexcept { return data_; }
    std::string_view Path() const noexcept { return path_; }
private:
    std::string path_;
    struct stat stat_;
    std::byte* data_ = nullptr;
};

#include "util.h"
