std::string StringToLower(std::string str) {
    for (auto& c : str) {
        if (c >= 'A' && c <= 'Z') c += 'a' - 'A';
    }
    return str;
}

std::string StringToUpper(std::string str) {
    for (auto& c : str) {
        if (c >= 'a' && c <= 'z') c -= 'a' - 'A';
    }
    return str;
}

std::string ReplaceAllSubstring(std::string_view str, std::string_view from, std::string_view to) {
    if (from.empty()) return std::string(str);
    std::string result;
    size_t start_pos = 0;
    size_t found_pos;
    while ((found_pos = str.find(from, start_pos)) != std::string::npos) {
        result.append(str.substr(start_pos, found_pos - start_pos));
        result.append(to);
        start_pos = found_pos + from.length();
    }
    result.append(str.substr(start_pos));
    return result;
}

std::vector<std::string> SplitString(const std::string& str, const std::regex& pattern) {
    std::vector<std::string> result;
    std::sregex_token_iterator it(str.begin(), str.end(), pattern, -1);
    std::sregex_token_iterator end;
    for (; it != end; ++it) {
        result.emplace_back(*it);
    }
    return result;
}

std::vector<std::string> SplitStringToLines(const std::string& str) {
    std::vector<std::string> result;
    std::istringstream iss(str);
    std::string line;
    while (std::getline(iss, line)) {
        result.push_back(line);
    }
    return result;
}

YAML::Node LoadYamlString(std::string_view str, std::initializer_list<std::string_view> required_fields) {
    YAML::Node node = YAML::Load(str);
    if (!node.IsMap()) throw std::runtime_error("Invalid YAML: root must be a map");
    for (auto field : required_fields) {
        if (!node[field.data()]) throw std::runtime_error(fmt::format("Missing required field: {}", field));
    }
    return node;
}

void ThrowIfYamlFieldIsNotScalar(const YAML::Node& node, std::string_view field) {
    if (!node[field.data()].IsScalar()) throw std::runtime_error(fmt::format("Field '{}' is not a scalar", field));
}

bool IsValidFileDescriptor(FileDescriptor fd) {
    return fd != invalid_file_descriptor && fcntl(fd, F_GETFD) != -1 || errno != EBADF;
}

void SetFileDescriptorAsNonblocking(FileDescriptor fd) {
    int flags = fcntl(fd, F_GETFL);
    if (flags == -1) ThrowLastSystemError();
    if (fcntl(fd, F_SETFL, flags | O_NONBLOCK) == -1) ThrowLastSystemError();
}

void ThrowLastSystemError() {
    throw std::system_error(errno, std::generic_category());
}

std::uint32_t CurrentThreadId() {
    return static_cast<std::uint32_t>(pthread_self());
}

void Backtrace(std::vector<std::string>& stack, std::size_t size, std::size_t skip) {
    void* buffer[1024];
    int frames = backtrace(buffer, static_cast<int>(std::min(size, sizeof(buffer)/sizeof(void*))));
    char** symbols = backtrace_symbols(buffer, frames);
    for (int i = skip; i < frames; ++i) {
        stack.emplace_back(symbols[i]);
    }
    free(symbols);
}

std::string Backtrace(std::size_t size, std::size_t skip, std::string_view prefix) {
    std::vector<std::string> stack;
    Backtrace(stack, size, skip);
    return fmt::format("{}{}", prefix, fmt::join(stack, "\n"));
}

std::byte* MappedReadOnlyFile::Map() {
    Unmap();
    path_ = path_; // Ensure path is set
    if (stat(path_.c_str(), &stat_) == -1) ThrowLastSystemError();
    FileDescriptor fd = open(path_.c_str(), O_RDONLY);
    if (fd == invalid_file_descriptor) ThrowLastSystemError();
    SetFileDescriptorAsNonblocking(fd);
    data_ = static_cast<std::byte*>(mmap(nullptr, stat_.st_size, PROT_READ, MAP_PRIVATE, fd, 0));
    close(fd);
    if (data_ == MAP_FAILED) ThrowLastSystemError();
    return data_;
}

void MappedReadOnlyFile::Unmap() {
    if (data_) {
        munmap(data_, stat_.st_size);
        data_ = nullptr;
    }
}
